// Attack Track (Red Team / Offensive) — added 12 Nov 2026 on the user's
// order. EVERY lesson and lab runs against an AUTHORIZED target only: the
// learner's own local training app, own lab VMs, own lab hashes, own AD lab,
// or a consented simulation inside the learner's own lab. No lesson teaches
// taking over real accounts or unauthorized access to real systems — the
// same skills are taught on lab targets and via bug bounty with test
// accounts (Level 11 / Level 22), which is the professional path.
// This track is deliberately NOT part of the Level 0–22 path chain: it is a
// parallel track gated by named prerequisite lessons + serial order inside
// the track itself.

export type AtkText = { en: string; bn: string };
export type AtkLesson = {
  id: string;
  title: string; bnTitle: string;
  minutes: number; xp: number;
  requires: string[]; // main-catalog lesson ids that must be complete
  target: AtkText; // the authorized target, named on the page
  intro: AtkText; // what you will learn + what you will do (2–3 lines)
  steps: { title: AtkText; body: AtkText }[]; // the 8-step attack format
  code: { lang: string; title: string; code: string; output: string };
  why: { why: AtkText; parts: AtkText; output: AtkText; job: AtkText; wrong: AtkText };
  note?: { idea: AtkText; body: AtkText };
  tips?: { en: string[]; bn: string[] };
  quiz: { q: string; options: string[]; answer: number; why: string }[];
  quizBn: { q?: string; why?: string }[];
  practical: { task: string; options: string[]; answer: number; explain: string; hint: string };
  practicalBn: { task: string; explain: string; hint: string };
  canDo: AtkText; // "what you can do now" close
};
export type AtkLab = {
  id: string; title: string; bnTitle: string; xp: number;
  requiresLesson: string; // attack lesson id that must be complete
  target: AtkText;
  artifactTitle: AtkText;
  artifact: string; // simulated lab artefact the learner inspects (labelled SIMULATED)
  tasks: { prompt: AtkText; options: string[]; bnOptions?: (string | undefined)[]; answer: number; explain: AtkText; hint: AtkText }[];
  flag: string;
};

const T = (en: string, bn: string): AtkText => ({ en, bn });

